// desactivación de las que ya no vienen en la lista nueva.
// ---------------------------------------------------------------------------
// Recibe uno o varios product_id — así Get (un id) y List (una página completa) usan la misma
// consulta sin caer en N+1 al hidratar varios productos con sus variantes.
func (q *Queries) ListVariantsByProducts(ctx context.Context, productIds []uuid.UUID) ([]ProductVariant, error) {
	rows, err := q.db.Query(ctx, listVariantsByProducts, productIds)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []ProductVariant{}
	for rows.Next() {
		var i ProductVariant
		if err := rows.Scan(
			&i.ID,
			&i.ProductID,
			&i.OrganizationID,
			&i.Name,
			&i.PriceCents,
			&i.IsDefault,
			&i.IsActive,
			&i.Position,
			&i.CreatedAt,
			&i.UpdatedAt,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

