const updateProduct = `-- name: UpdateProduct :one
UPDATE products
SET category_id  = CASE WHEN $1::boolean THEN $2 ELSE category_id END,
    name         = COALESCE($3, name),
    description  = CASE WHEN $4::boolean THEN $5 ELSE description END,
    image_url    = CASE WHEN $6::boolean THEN $7 ELSE image_url END,
    position     = COALESCE($8, position),
    is_active    = COALESCE($9, is_active),
    ingredients  = CASE WHEN $10::boolean THEN $11::text[] ELSE ingredients END,
    channels     = CASE WHEN $12::boolean THEN $13::text[] ELSE channels END,
    promo_discount_bps = COALESCE($14, promo_discount_bps),
    updated_at   = now()
WHERE id = $15 AND organization_id = $16
RETURNING id, organization_id, category_id, name, description, image_url, position, is_active, created_at, updated_at, ingredients, channels, promo_discount_bps
`

type UpdateProductParams struct {
	SetCategory      bool
	CategoryID       uuid.NullUUID
	Name             *string
	SetDescription   bool
	Description      *string
	SetImage         bool
	ImageUrl         *string
	Position         *int32
	IsActive         *bool
	SetIngredients   bool
	Ingredients      []string
	SetChannels      bool
	Channels         []string
	PromoDiscountBps *int32
	ID               uuid.UUID
	OrganizationID   uuid.UUID
}

// Cambio parcial: set_* distingue "no tocar" de "reemplazar" para los campos que no se pueden
// expresar con un simple ausente (category_id/description/image_url admiten null; ingredients y
// channels son arreglos, y un arreglo vacío es un valor real — "sin ingredientes", "sin publicar
// en ningún canal" — no "no tocar"). name/position/is_active nunca se ponen en blanco, así que
// un ausente (COALESCE) basta ahí.
func (q *Queries) UpdateProduct(ctx context.Context, arg UpdateProductParams) (Product, error) {
	row := q.db.QueryRow(ctx, updateProduct,
		arg.SetCategory,
		arg.CategoryID,
		arg.Name,
		arg.SetDescription,
		arg.Description,
		arg.SetImage,
		arg.ImageUrl,
		arg.Position,
		arg.IsActive,
		arg.SetIngredients,
		arg.Ingredients,
		arg.SetChannels,
		arg.Channels,
		arg.PromoDiscountBps,
		arg.ID,
		arg.OrganizationID,
	)
	var i Product
	err := row.Scan(
		&i.ID,
		&i.OrganizationID,
		&i.CategoryID,
		&i.Name,
		&i.Description,
		&i.ImageUrl,
		&i.Position,
		&i.IsActive,
		&i.CreatedAt,
		&i.UpdatedAt,
		&i.Ingredients,
		&i.Channels,
		&i.PromoDiscountBps,
	)
	return i, err
}

